object LocaleManager {
    private val _currentLanguage = MutableStateFlow("en")
    val currentLanguage: StateFlow<String> = _currentLanguage.asStateFlow()

    val supportedLanguages = listOf(
        Triple("en", "English", "English"),
        Triple("hi", "Hindi", "हिंदी"),
        Triple("as", "Assamese", "অসমীয়া"),
        Triple("bn", "Bengali", "বাংলা"),
        Triple("mni", "Manipuri", "ꯃꯏꯇꯩꯂꯣꯟ"),
        Triple("lus", "Mizo", "Mizo"),
        Triple("kha", "Khasi", "Khasi"),
    )

    fun init() {
        _currentLanguage.value = SecurePreferences.getLanguage()
    }

    fun setLanguage(code: String) {
        _currentLanguage.value = code
        SecurePreferences.setLanguage(code)
    }
}

