    fun get(key: String, lang: String = LocaleManager.currentLanguage.value): String {
        return translations[lang]?.get(key) ?: translations["en"]?.get(key) ?: key
    }

    @Composable
    operator fun invoke(key: String): String {
        val lang by LocaleManager.currentLanguage.collectAsState()
        return translations[lang]?.get(key) ?: translations["en"]?.get(key) ?: key
    }
